style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
/* Base background + text */
  html, body {
    background-color: #f5f1e6 !important; /* beige */
    color: #111111 !important;            /* near-black text */
  }

  /* General text */
  p, span, div, li, td, th, h1, h2, h3, h4, h5, h6, strong, b {
    color: #111111 !important;
    background: transparent !important; /* remove highlights */
  }

  /* Inputs (keep readable but minimal) */
  input, textarea, select {
    background-color: #ffffff !important;
    color: #111111 !important;
    border: 1px solid #ccc !important;
  }

  /* Links */
  a {
    color: #111111 !important;
    text-decoration: underline !important;
  }

  /* Buttons: don’t restyle, just keep text dark */
  button, [role="button"] {
    color: #111111 !important;
    background: transparent !important;
    border: 1px solid #aaa !important;
  }

  /* Remove extra forced backgrounds (stops ugly highlights) */
  header, nav, footer, section, article, aside {
    background: transparent !important;
    color: inherit !important;
  }

  /* Scrollbars (simple minimal) */
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: #f5f1e6; }
  ::-webkit-scrollbar-thumb { background: #999; border-radius: 6px; }
}
